79: func (r *limitedReader) Read(b []byte) (n int, err error) {
80: 	if r.err != nil {
81: 		return 0, r.err
82: 	}
83: 	if len(b) == 0 {
84: 		return 0, nil
85: 	}
86: 	remaining := r.LimitBytes - r.read
87: 	// If the caller asked for more bytes than are still allowed, cap the
88: 	// buffer one byte past the limit. That single extra byte is enough to
89: 	// tell whether the underlying reader holds more data than allowed,
90: 	// without ever reading more of it than necessary.
91: 	if int64(len(b))-1 > remaining {
92: 		b = b[:remaining+1]
93: 	}
94: 	n, err = r.reader.Read(b)
95: 
96: 	if int64(n) <= remaining {
97: 		r.read += int64(n)
98: 		return n, err
99: 	}
100: 
101: 	// The underlying reader offered more data than the limit allows. Only
102: 	// hand out the allowed portion and make the error sticky, so callers
103: 	// that process the n>0 bytes before handling the error (as io.Reader
104: 	// documents) cannot read any further data on subsequent calls.
105: 	n = int(remaining)
106: 	r.read = r.LimitBytes
107: 	r.err = echo.ErrStatusRequestEntityTooLarge
108: 	return n, r.err
109: }

